<?php $this->view('page_components/header'); ?>
<div class="page-heading"><div class="page-title"><h3>Dokumenty transportowe</h3><p class="text-subtitle text-muted">CMR oraz ewidencja i raporty opakowań BDO / PPWR dla zrealizowanych wysyłek.</p></div>
<section class="section"><div class="card"><div class="card-body">
<div class="row mb-3"><div class="col-md-5"><input class="form-control" id="filterCompany" placeholder="Filtruj po nazwie klienta"></div><div class="col-md-5"><input class="form-control" type="date" id="filterDate"></div><div class="col-md-2"><button class="btn btn-outline-secondary w-100" type="button" onclick="clearFilters()">Wyczyść</button></div></div>
<div class="table-responsive"><table class="table table-hover align-middle" id="transportDocumentsTable"><thead><tr><th>Data</th><th>Klient</th><th>CMR</th><th>BDO</th><th>PPWR</th></tr></thead><tbody><?php foreach ($generated_docs ?? [] as $row): ?><tr><td><?= htmlspecialchars($row['shipment_date']) ?></td><td><?= htmlspecialchars($row['company']) ?></td>
<td><button class="btn btn-outline-dark" onclick="downloadPDF('/ajax/cmr-documents/<?= (int)$row['id_cmr'] ?>/document')" type="button">CMR [PDF]</button></td>
<td><?php if (!empty($row['packaging_status'])): ?><?php if (($row['packaging_status'] ?? null) === 'REQUIRES_DATA'): ?><div><span class="badge bg-warning text-dark mb-1">Braki: <?= (int)$row['packaging_issue_count'] ?></span></div><?php endif; ?><button class="btn btn-success" onclick="downloadPDF('/ajax/shipments/<?= (int)$row['id'] ?>/documents/packaging')" type="button">BDO [PDF]</button><?php else: ?><button class="btn btn-primary" onclick="createBdoEvidence(<?= (int)$row['id'] ?>)" type="button">Utwórz BDO</button><?php endif; ?></td>
<td><button id="ppwr-action-<?= (int)$row['id'] ?>" class="btn <?= empty($row['ppwr_evidence_basis']) ? 'btn-primary' : 'btn-outline-primary' ?>" onclick="<?= empty($row['ppwr_evidence_basis']) ? 'createPpwrEvidence(' . (int)$row['id'] . ')' : 'downloadPpwr(' . (int)$row['id'] . ')' ?>" type="button"><?= empty($row['ppwr_evidence_basis']) ? 'Generuj PPWR [PDF]' : 'Pobierz PPWR [PDF]' ?></button><div id="ppwr-status-<?= (int)$row['id'] ?>" class="small <?= empty($row['ppwr_evidence_basis']) ? 'text-muted' : (($row['ppwr_evidence_basis'] === 'CURRENT_DATA_RECONSTRUCTION') ? 'text-warning' : 'text-success') ?>"><?= empty($row['ppwr_evidence_basis']) ? 'Brak raportu PPWR' : (($row['ppwr_evidence_basis'] === 'CURRENT_DATA_RECONSTRUCTION') ? 'Dane bieżące' : 'Snapshot wysyłki') ?></div></td></tr><?php endforeach; ?></tbody></table></div></div></div></section></div>
<?php $this->view('page_components/footer'); ?>
<script>
function downloadPpwr(id) { downloadPDF('/ajax/shipments/' + id + '/documents/ppwr'); }
async function createPpwrEvidence(id) { if (!confirm('Dla dostawy bez historycznego snapshotu PPWR raport zostanie odtworzony z bieżącej receptury i profili PPWR. Czy kontynuować?')) return; const response = await fetch('<?= ROOT ?>/ajax/shipments/' + id + '/ppwr-evidence/current-data', {method:'POST',headers:{'Accept':'application/json'},credentials:'same-origin'}), payload = await response.json().catch(() => ({})); if (!response.ok) return alert(payload.message || 'Nie udało się przygotować raportu PPWR.'); const action=document.getElementById('ppwr-action-'+id), status=document.getElementById('ppwr-status-'+id), reconstructed=Boolean(payload.data?.reconstructed); action.className='btn btn-outline-primary'; action.textContent='Pobierz PPWR [PDF]'; action.onclick=()=>downloadPpwr(id); status.className='small '+(reconstructed?'text-warning':'text-success'); status.textContent=reconstructed?'Dane bieżące':'Snapshot wysyłki'; downloadPpwr(id); }
async function createBdoEvidence(id) { if (!confirm('Ewidencja BDO zostanie wyliczona z bieżącej receptury i danych opakowań. Czy kontynuować?')) return; const response=await fetch('<?= ROOT ?>/ajax/shipments/'+id+'/packaging-evidence/current-data',{method:'POST',headers:{'Accept':'application/json'},credentials:'same-origin'}), payload=await response.json().catch(()=>({})); if(!response.ok) return alert(payload.message||'Nie udało się utworzyć ewidencji BDO.'); location.reload(); }
function filterTable(){const company=filterCompany.value.toLowerCase(),date=filterDate.value;document.querySelectorAll('#transportDocumentsTable tbody tr').forEach(row=>row.style.display=(!company||row.cells[1].textContent.toLowerCase().includes(company))&&(!date||row.cells[0].textContent.trim()===date)?'':'none');} function clearFilters(){filterCompany.value='';filterDate.value='';filterTable();} filterCompany.addEventListener('input',filterTable);filterDate.addEventListener('input',filterTable);
</script>
